export function requireValue<T>(input: T): NonNullable<T> {
 if (input == null) throw 0;
 return input;
}
export const value = requireValue("ok");

import type { Payload } from "./types";
declare const input: NonNullable<Payload | null>;
export const value = input;

type RequiredValues<T> = {[K in keyof T]: NonNullable<T[K]>};
declare const input: RequiredValues<{x: string | null; y: number | undefined}>;
export const value = input;

type Present<T> = T extends unknown ? NonNullable<T> : never;
declare const input: Present<string | number | null>;
export const value = input;

type Fields = NonNullable<{a: number; b: string} | undefined>;
declare const input: keyof Fields;
export const value = input;

declare const value: NonNullable<{readonly x: number} | null>;
value.x = 2;
export { value };

type Thenable = {then(onfulfilled: (value: number) => void): void};
declare const input: Awaited<Thenable>;
export const value = input;

type Thenable = {then(onfulfilled: (value: number) => void): void};
declare const input: Awaited<Thenable | string>;
export const value = input;

type Thenable = {then(onfulfilled: (value: {then(cb: (value: number) => void): void}) => void): void};
declare const input: Awaited<Thenable>;
export const value = input;

type Thenable = {then(onfulfilled: (value: number) => void): void};
declare const input: Awaited<string & Thenable>;
export const value = input;

type Thenable = {then(onfulfilled: (value: number) => void): void};
declare const input: Awaited<number & Thenable>;
export const value = input;

type Thenable = {then: number};
declare const input: Awaited<Thenable>;
export const value = input;

type Thenable = {then?: (onfulfilled: (value: number) => void) => void};
declare const input: Awaited<Thenable>;
export const value = input;

type Thenable = {then(onfulfilled: number): void};
declare const input: Awaited<Thenable>;
export const value = input;

type Thenable = {then(onfulfilled: () => void): void};
declare const input: Awaited<Thenable>;
export const value = input;

type Thenable = {then(onfulfilled: (value: number, second: string) => void, extra: boolean): void};
declare const input: Awaited<Thenable>;
export const value = input;

type Thenable = {then(onfulfilled: (...args: [number, string]) => void): void};
declare const input: Awaited<Thenable>;
export const value = input;

interface Thenable {then(onfulfilled: (value: number) => void): void; then(onfulfilled: (value: string) => void): void;}
declare const input: Awaited<Thenable>;
export const value = input;

interface Callback {(value: number): void; (value: string): void;}
type Thenable = {then(onfulfilled: Callback): void};
declare const input: Awaited<Thenable>;
export const value = input;

type Thenable = {then(onfulfilled: (value: number) => void): void};
type Inner = Thenable; type Outer = Inner;
declare const input: Awaited<Outer>;
export const value = input;

import type { Thenable } from "./types";
declare const input: Awaited<Thenable>;
export const value = input;

interface Box<T> {then(onfulfilled: (value: T) => void): void;}
declare const input: Awaited<Box<number>>;
export const value = input;

export declare function unwrap<T>(value: T): Awaited<T>;
declare const input: PromiseLike<number>;
export const value = unwrap(input);

type Thenable = {then(onfulfilled: (value: number) => void): void};
declare function accept(value: Awaited<Thenable>): void;
accept("bad");
export {};

interface Recursive {then(onfulfilled: (value: Recursive) => void): void;}
declare const input: Awaited<Recursive>;
export const value = input;

interface First {then(cb: (value: Second) => void): void;}
interface Second {then(cb: (value: First) => void): void;}
declare const input: Awaited<First>;
export const value = input;

// 😀
type Thenable = {then(cb: (value: number) => void): void};
export const value: Awaited<Thenable> = "bad";

export function requireValue<T>(input: T): NonNullable<T> {if(input == null) throw 0; return input;}
export const value = requireValue(7);
if (value !== 7) throw 1;

export function identity(value: number): Awaited<number> {return value;}
export const value = identity(7);
if (value !== 7) throw 1;

type Thenable = ((input: boolean) => void) & {then(onfulfilled: (value: number) => void): void};
declare const input: Awaited<Thenable>;
export const value = input;

type Thenable = {then<T>(onfulfilled: (value: T) => void): void};
declare const input: Awaited<Thenable>;
export const value = input;

type Thenable = {then(onfulfilled: ((value: number) => void) | number): void};
declare const input: Awaited<Thenable>;
export const value = input;

const Promise = {resolve(value: number) {return value;}};
export const value = Promise.resolve(7);
if (value !== 7) throw 1;
